"image-promotion.yml:promote": {
  "source": {
    "job": {
      "runs-on": "ubuntu-latest",
      "steps": [
        {
          "uses": "actions/checkout@v7"
        },
        {
          "name": "Install repository-pinned Rust toolchain",
          "run": "set -euo pipefail\ntoolchain=\"$(sed -n 's/^channel = \"\\([^\"\\]*\\)\"/\\1/p' rust-toolchain.toml)\"\ntest \"$toolchain\" = \"1.99.0\"\nrustup toolchain install \"$toolchain\" --profile minimal\n"
        },
        {
          "name": "Confirm pinned Rust toolchain",
          "run": "rustup run 1.99.0 rustc --version --verbose"
        },
        {
          "name": "Recover an interrupted native digest transaction",
          "run": "cargo xtask ci-helper image-pin-promote --recover"
        },
        {
          "name": "Cross-check the native digest tool against the pinned state",
          "run": "set +e\ncargo xtask ci-helper image-pin-promote --check\ncode=$?\nset -e\ncase \"$code\" in\n  0|1) ;;\n  *) echo \"::error::Native digest check failed (exit $code).\"; exit 1 ;;\nesac\n"
        },
        {
          "name": "Promote pinned image digest if CI published a newer one",
          "id": "promote",
          "run": "set +e\ncargo xtask ci-helper image-pin-promote --write --root .\ncode=$?\nset -e\ncase \"$code\" in\n  0|10) ;;\n  *) echo \"::error::Native digest promotion failed (exit $code); inspect retained recovery journal.\"; exit 1 ;;\nesac\ncargo xtask ci-helper image-pin-promote --recover\ntest ! -e .ssx-image-promotion\ntest ! -e .ssx-image-promotion-cleanup.json\ntest ! -e .ssx-image-promotion-cleanup.pending\necho \"changed=$(git status --porcelain | wc -l | tr -d ' ')\" >> \"$GITHUB_OUTPUT\"\n"
        },
        {
          "name": "Open or update promotion PR",
          "if": "steps.promote.outputs.changed != '0'",
          "uses": "peter-evans/create-pull-request@v8",
          "with": {
            "add-paths": "docker-compose.yml\nk8s/deployment.yaml\ntests/test_deployment_artifacts.py\nspec.md\n",
            "branch": "chore/promote-image-digest",
            "delete-branch": true,
            "labels": "ci,automated",
            "commit-message": "chore: promote slopsearx image digest to current latest",
            "title": "chore: promote slopsearx image digest to current latest",
            "body": "Automated promotion of the digest-pinned application image\n(`ghcr.io/magnus919/slopsearx`) in docker-compose.yml,\nk8s/deployment.yaml, tests/test_deployment_artifacts.py, and the\ntwo spec.md examples, so deployments track the\nartifact CI most recently built, Trivy-scanned, and smoke-tested\non main (#210).\n\nGenerated by `.github/workflows/image-promotion.yml`. The native\n`cargo xtask ci-helper image-pin-promote` recovers interrupted local\ntransactions, checks drift, and writes the four reviewed digest operands.\nRegistry publication and deployment remain separate operations.\n"
          }
        }
      ]
    },
    "workflow": {
      "name": "Image Digest Promotion",
      "on": {
        "schedule": [
          {
            "cron": "23 5 * * *"
          }
        ],
        "workflow_dispatch": null
      },
      "permissions": {
        "contents": "write"
      }
    }
  },
  "owner": "O04",
  "state": "pending-owner",
  "successor": "cargo xtask check O04; native registry digest resolver, index/platform checks and config update; retain create-pull-request integration and immutable digest review"
},
